  1209  /**
  1210   * Internal: enumerate contents of a data blob.
  1211   * The OpenPGP card has a TLV encoding according ASN.1 BER-encoding rules.
  1212   */
  1213  static int
  1214  pgp_enumerate_blob(sc_card_t *card, pgp_blob_t *blob)
  1215  {
  1216          const u8        *in;
  1217          int             r;
  1218
  1219          if (blob->files != NULL)
  1220                  return SC_SUCCESS;
  1221
  1222          if ((r = pgp_read_blob(card, blob)) < 0)
  1223                  return r;
  1224
  1225          in = blob->data;
  1226
  1227          while ((int) blob->len > (in - blob->data)) {
  1228                  unsigned int    cla, tag, tmptag;
  1229                  size_t          len;
  1230                  const u8        *data = in;
  1231                  pgp_blob_t      *new;
  1232
  1233                  if (!in)
  1234                          return SC_ERROR_OBJECT_NOT_VALID;
  1235
  1236                  r = sc_asn1_read_tag(&data, blob->len - (in - blob->data),
  1237                                          &cla, &tag, &len);
  1238                  if (r < 0 || data == NULL) {
  1239                          sc_log(card->ctx,
  1240                                   "Unexpected end of contents\n");
  1241                          return SC_ERROR_OBJECT_NOT_VALID;
  1242                  }
  1243
  1244                  if (data + len > blob->data + blob->len)
  1245                          return SC_ERROR_OBJECT_NOT_VALID;
  1246
  1247                  /* undo ASN1's split of tag & class */
  1248                  for (tmptag = tag; tmptag > 0x0FF; tmptag >>= 8) {
  1249                          cla <<= 8;
  1250                  }
  1251                  tag |= cla;
  1252
  1253                  /* Awful hack for composite DOs that have
  1254                   * a TLV with the DO's id encompassing the
  1255                   * entire blob. Example: Yubikey Neo */
  1256                  if (tag == blob->id) {
  1257                          in = data;
  1258                          continue;
  1259                  }
  1260
  1261                  /* create fake file system hierarchy by
  1262                   * using constructed DOs as DF */
  1263                  if ((new = pgp_new_blob(card, blob, tag, sc_file_new())) == NULL)
  1264                          return SC_ERROR_OUT_OF_MEMORY;
  1265                  pgp_set_blob(new, data, len);
  1266                  in = data + len;
  1267          }
  1268
  1269          return SC_SUCCESS;
  1270  }
