  1691          sc_apdu_t       apdu;
  1692          int             r;
  1693
  1694          LOG_FUNC_CALLED(card->ctx);
  1695
  1696          sc_format_apdu(card, &apdu, SC_APDU_CASE_2, 0xCA, tag >> 8, tag);
  1697          apdu.le = ((buf_len >= 256) && !(card->caps & SC_CARD_CAP_APDU_EXT)) ? 256 : buf_len;
  1698          apdu.resp = buf;
  1699          apdu.resplen = buf_len;
  1700
  1701          r = sc_transmit_apdu(card, &apdu);
  1702          LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
  1703
  1704          r = sc_check_sw(card, apdu.sw1, apdu.sw2);
  1705
  1706          /* Gnuk returns an error instead of empty data if there is no certificate or private DO.
  1707           * So, for this case, we ignore error and consider success */
  1708          if (card->type == SC_CARD_TYPE_OPENPGP_GNUK &&
  1709              (tag == DO_CERT  ||
  1710               tag == DO_PRIV1 ||
  1711               tag == DO_PRIV2 ||
  1712               tag == DO_PRIV3 ||
  1713               tag == DO_PRIV4)) {
  1714                  if (r == SC_ERROR_DATA_OBJECT_NOT_FOUND) {
  1715                          r = SC_SUCCESS;
  1716                          apdu.resplen = 0;
  1717                  }
  1718          }
  1719          LOG_TEST_RET(card->ctx, r, "Card returned error");
  1720
  1721          LOG_FUNC_RETURN(card->ctx, (int)apdu.resplen);
  1722  }
